from collections import deque
import random

def bfs_shortest_cycle_from_edge(graph, u, v, max_len=6):
    """Find shortest cycle containing edge (u,v), up to max_len.
    Returns cycle length or infinity."""
    # BFS from u, avoiding edge (u,v) initially
    # Actually, BFS from v in graph minus edge (u,v), looking for u
    dist = {v: 0}
    parent = {v: None}
    q = deque([v])
    while q:
        x = q.popleft()
        if dist[x] >= max_len // 2:
            continue
        for y in graph[x]:
            if (x == u and y == v) or (x == v and y == u):
                continue  # skip the edge we're checking
            if y not in dist:
                dist[y] = dist[x] + 1
                parent[y] = x
                q.append(y)
                if y == u:
                    return dist[y] + 1
    return float('inf')

def check_girth(graph, max_check=6):
    """Check that graph has no cycles of length <= max_check."""
    for u in graph:
        for v in graph[u]:
            if u < v:  # only check each edge once
                cycle_len = bfs_shortest_cycle_from_edge(graph, u, v, max_check)
                if cycle_len <= max_check:
                    return False, (u, v, cycle_len)
    return True, None

def solve_backtrack():
    A = list(range(8))
    B = list(range(8, 16))

    # All possible edges
    all_edges = [(a, b) for a in A for b in B]

    # Sort edges randomly for different attempts
    random.seed(42)

    best_edges = []
    best_count = 0

    for attempt in range(1000):
        edges = []
        graph = {i: set() for i in range(16)}
        random.shuffle(all_edges)

        for a, b in all_edges:
            # Try adding edge (a,b)
            graph[a].add(b)
            graph[b].add(a)
            ok, info = check_girth(graph, 6)
            if ok:
                edges.append((a, b))
                if len(edges) >= 21:
                    return edges, graph
            else:
                graph[a].remove(b)
                graph[b].remove(a)

        if len(edges) > best_count:
            best_count = len(edges)
            best_edges = edges[:]
            print(f"Attempt {attempt}: found {len(edges)} edges")
            if len(edges) >= 21:
                return edges, graph

    return best_edges, None

