from collections import deque

def find_all_cycles(graph, max_len=7):
    cycles = []
    for start in range(16):
        # BFS from start
        dist = {start: 0}
        parent = {start: None}
        q = deque([start])
        while q:
            u = q.popleft()
            if dist[u] >= max_len:
                continue
            for v in graph[u]:
                if v == parent[u]:
                    continue
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif dist[v] < dist[u]:  # found a cycle
                    # trace back
                    cycle = [u]
                    x = u
                    while x != v:
                        x = parent[x]
                        cycle.append(x)
                    cycle_len = len(cycle)
                    if cycle_len <= max_len and cycle_len >= 3:
                        cycles.append((cycle_len, tuple(sorted(cycle))))
    return cycles

