from collections import defaultdict, deque

def build_tree():
    # Tree: root 0, three branches of length 5
    # 0-1-2-3-4-5, 0-6-7-8-9-10, 0-11-12-13-14-15
    edges = []
    # Branch 1
    for i in range(5):
        edges.append((i, i+1))
    # Branch 2
    edges.append((0, 6))
    for i in range(6, 10):
        edges.append((i, i+1))
    # Branch 3
    edges.append((0, 11))
    for i in range(11, 15):
        edges.append((i, i+1))
    return edges

def get_distances(tree_edges):
    graph = defaultdict(list)
    for u, v in tree_edges:
        graph[u].append(v)
        graph[v].append(u)

    dist = {}
    for start in range(16):
        d = {start: 0}
        q = deque([start])
        while q:
            u = q.popleft()
            for v in graph[u]:
                if v not in d:
                    d[v] = d[u] + 1
                    q.append(v)
        dist[start] = d
    return dist

