def find_shortest_cycle(graph, max_len=7):
    """Find shortest cycle in graph, up to max_len."""
    for start in range(16):
        # BFS from start
        q = deque([(start, None, 0)])  # (node, parent, depth)
        visited = {start: (None, 0)}  # node -> (parent, depth)
        while q:
            u, p, d = q.popleft()
            if d >= max_len:
                continue
            for v in graph[u]:
                if v == p:
                    continue
                if v in visited:
                    # Found a cycle
                    cycle_len = d + 1 + visited[v][1]
                    if cycle_len <= max_len and cycle_len >= 3:
                        return cycle_len
                else:
                    visited[v] = (u, d + 1)
                    q.append((v, u, d + 1))
    return None

