import random
from collections import defaultdict, deque

def find_all_short_cycles(graph, max_len=7):
    """Find all cycles of length <= max_len."""
    cycles = []
    for start in range(16):
        # BFS from start, tracking paths
        q = deque([(start, [start])])
        while q:
            path = q.popleft()
            u = path[-1]
            if len(path) > max_len + 1:
                continue
            for v in graph[u]:
                if v == path[-2] if len(path) >= 2 else False:
                    continue
                if v == start and len(path) >= 3:
                    cycles.append(tuple(path))
                elif v not in path and len(path) < max_len:
                    q.append(path + [v])
    return cycles

def find_one_short_cycle(graph, max_len=7):
    """Find one cycle of length <= max_len."""
    for start in range(16):
        q = deque([(start, [start])])
        visited = set()
        while q:
            path = q.popleft()
            u = path[-1]
            if len(path) > max_len + 1:
                continue
            for v in graph[u]:
                if len(path) >= 2 and v == path[-2]:
                    continue
                if v == start and len(path) >= 3 and len(path) <= max_len + 1:
                    return path
                if v not in path and len(path) < max_len:
                    new_path = path + [v]
                    q.append(new_path)
    return None

def local_search(iterations=100000):
    # Start with empty graph
    edges = []
    graph = defaultdict(set)

    # Candidate edges
    candidates = [(u, v) for u in range(16) for v in range(u+1, 16)]

    for i in range(iterations):
        if len(edges) < 21:
            # Try adding a random edge
            u, v = random.choice(candidates)
            if v not in graph[u]:
                graph[u].add(v)
                graph[v].add(u)
                cycle = find_one_short_cycle(graph, 7)
                if cycle is None:
                    edges.append((u, v))
                else:
                    graph[u].remove(v)
                    graph[v].remove(u)
        else:
            # We have 21 edges, try to maintain
            # Remove a random edge and try to add a different one
            if len(edges) > 0:
                idx = random.randint(0, len(edges) - 1)
                ru, rv = edges[idx]
                graph[ru].remove(rv)
                graph[rv].remove(ru)
                edges.pop(idx)

        if i % 10000 == 0:
            print(f"Iteration {i}: {len(edges)} edges")
            if len(edges) >= 21:
                print(f"Found 21 edges!")
                return edges

    return edges

